    # Tokenize the message and convert it to a tensor
    inputs = tokenizer(message, return_tensors='pt', padding=True, truncation=True)
    # Pass the message through the BERT model to obtain the output
    with torch.no_grad():
        outputs = model(**inputs)
    # Get the predicted label (0 for negative, 1 for positive)
    predicted_label = torch.argmax(outputs.logits).item()
    # Get the sentiment score using the VADER model
